def fewest_switches(switches, target):
    want = int(target, 2)
    masks = [int(s, 2) for s in switches]
    if want == 0 and not masks:
        return []
    for size in range(1, len(masks) + 1):
        for pick in combinations(range(len(masks)), size):
            lit = 0
            for i in pick:
                lit ^= masks[i]
